 document.addEventListener('DOMContentLoaded', function() {
    // 1) Abrir/fechar dropdown ao clicar no botão
    document.querySelectorAll('.custom-language-switcher .cls-selected').forEach(function(selectedEl) {
      selectedEl.addEventListener('click', function(e) {
        e.stopPropagation();
        var wrapper = this.closest('.custom-language-switcher');
        wrapper.classList.toggle('open');
      });
    });

    // 2) Ao clicar numa opção, faz o redirecionamento
    document.querySelectorAll('.custom-language-switcher .cls-option').forEach(function(optionEl) {
      optionEl.addEventListener('click', function(e) {
        var url = this.getAttribute('data-url');
        if ( url ) {
          window.location.href = url;
        }
      });
    });

    // 3) Fecha o dropdown se clicar fora
    document.addEventListener('click', function() {
      document.querySelectorAll('.custom-language-switcher.open').forEach(function(wrapper) {
        wrapper.classList.remove('open');
      });
    });
  });